function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  if (nums1.length !== nums2.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.length < 1 || nums1.length > 100) return 'The arrays need 1 to 100 values.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each value is an integer from 0 to 100.';
  return null;
}

