function countSubranges(nums1, nums2) {
  const MOD = 1000000007;
  const n = nums1.length;
  let offset = 0;
  let width = 1;
  for (let i = 0; i < n; i++) {
    offset += nums2[i];
    width += nums1[i] + nums2[i];
  }
  let dp = new Array(width).fill(0);
  let count = 0;
  for (let i = 0; i < n; i++) {
    const next = new Array(width).fill(0);
    next[offset + nums1[i]] += 1;
    next[offset - nums2[i]] += 1;
    for (let d = 0; d < width; d++) {
      if (dp[d] === 0) continue;
      next[d + nums1[i]] = (next[d + nums1[i]] + dp[d]) % MOD;
      next[d - nums2[i]] = (next[d - nums2[i]] + dp[d]) % MOD;
    }
    count = (count + next[offset]) % MOD;
    dp = next;
  }
  return count;
}

