      const len = r - l + 1;
      for (let mask = 0; mask < (1 << len); mask++) {
        let fromFirst = 0, fromSecond = 0;
        for (let j = 0; j < len; j++) {
          if ((mask >> j) & 1) fromFirst += nums1[l + j];
          else fromSecond += nums2[l + j];
